import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('Validation logging contract [specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('reports both rejected identifier paths and types without their values', async () => {
    const lines: string[] = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>) => {
      lines.push(JSON.stringify({category, message, fields}));
    };
    setLogger({debug: record, info: record, warn: record, error: record});
    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'lookup',
          description: 'Lookup by identifiers',
          inputSchema: {type: 'object', properties: {ssn: {type: 'string'}, phone: {type: 'string'}}},
        },
        async input => JSON.stringify(input)
      );
      const response = await registry.execute('lookup', {ssn: 123456789, phone: 987654321});
      const output = JSON.stringify({lines, response});

      expect({
        warnings: lines,
        response: response.result,
        leaksValue: output.includes('123456789') || output.includes('987654321'),
      }).toEqual({
        warnings: [expect.stringMatching(/ssn.*string.*phone.*string/)],
        response: expect.stringMatching(/ssn.*string.*phone.*string/),
        leaksValue: false,
      });
    } finally {
      setLogger();
    }
  });
});
EOF
